import { BookOpen, Calculator, ClipboardCheck, FileSearch, FolderKanban, LogOut, type LucideIcon } from 'lucide-react';
import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { BrowserRouter, NavLink, Navigate, Route, Routes } from 'react-router-dom';
import katex from 'katex';
import './index.css';
import { Badge, Button, Card, Field, Input } from './components/ui';

type User={id:number;username:string;role:'admin'|'user'};type Variable={code:string;label?:string;unit?:string;required?:boolean};type FormulaRule={kind?:string;expression?:string;result_key?:string;conditions?:Array<{expression:string;message?:string}>;table?:{input?:string;output?:string;rows?:Array<Record<string,number>>};source_crop_path?:string;substitution_latex?:string;calculation_chain?:string[]};type Formula={id:number;code:string;name:string;citation:string;page_number?:number;version_id?:number;version:number;status:string;latex:string;rule:FormulaRule;variables:Variable[];dependencies:string[];chapter_id?:number;chapter_number?:string;chapter_title?:string};type Stats={published:number;drafts:number;ocr_pages:number;calculations:number};type OcrAsset={id:number;page_number:number;block_count:number;formula_crop_count:number};type OcrPage={page_number:number;page_image:string;blocks:Array<{id:number;sequence:number;corrected_text:string;raw_text:string}>;formulas:Array<{id:number;recognized_latex:string;confirmed:number}>};type OcrFormulaDraft={id:number;page_number:number;sequence:number;ocr_text:string;ocr_latex?:string;raw_formula_label:string;suggested_code:string;source_crop_path:string;article_context:string;variable_context:string[];review_status:'draft_only';engine_status:string};
type ResultValue={name:string;value:number;unit:string;citation?:string;version?:number};
const parameterSymbols:Record<string,string>={K:'K',n:'n',Fx:'ΣFx',Fy:'ΣFy',alpha:'α',beta:'β'};
function MathSymbol({token}:{token:string}){const subscript=token.match(/^(?:Σ)?([NF])([xyz])$/);if(subscript){const [,letter,index]=subscript;return <span className="math-symbol">{token.startsWith('Σ')?'Σ':''}{letter}<sub>{index}</sub></span>}const value=token==='alpha'?'α':token==='beta'?'β':parameterSymbols[token]||token;return <span className="math-symbol">{value}</span>}
function ParameterLabel({variable}:{variable:Variable}){const symbol=parameterSymbols[variable.code]||variable.code;const label=(variable.label||'').replace(/ΣFx|ΣFy|alpha|beta|K|n|α|β/g,'').trim();return <>{label&&<>{label} </>}<MathSymbol token={symbol}/></>}
const mathTokens=new Set(['ΣFx','ΣFy','Nx','Ny','Nz','Fx','Fy','alpha','beta','α','β','K','n','N']);
function FormulaText({children}:{children:string}){return <>{children.split(/(ΣFx|ΣFy|Nx|Ny|Nz|Fx|Fy|alpha|beta|α|β|(?<![A-Za-z])K(?![A-Za-z])|(?<![A-Za-z])n(?![A-Za-z])|(?<![A-Za-z])N(?![A-Za-z]))/).map((part,index)=>mathTokens.has(part)?<MathSymbol key={index} token={part}/>:part)}</>}
const resultMeanings:Record<string,{label:string;meaning:string}>={
  '10.2.1-1':{label:'系缆力标准值 N',meaning:'由风和水流共同作用产生的系缆力标准值（kN）。'},
  '10.2.1-2':{label:'横向分力 Nx',meaning:'系缆力标准值垂直于码头前沿线的横向分力（kN）。'},
  '10.2.1-3':{label:'纵向分力 Ny',meaning:'系缆力标准值平行于码头前沿线的纵向分力（kN）。'},
  '10.2.1-4':{label:'竖向分力 Nz',meaning:'系缆力标准值垂直于码头面的竖向分力（kN）。'},
};
const resultMeaning=(code:string,item?:Partial<ResultValue>)=>resultMeanings[code]||{label:item?.name||code,meaning:''};
const request=async<T,>(path:string,token:string|null,method='GET',body?:unknown)=>{const r=await fetch(path,{method,headers:{...(token?{Authorization:`Bearer ${token}`} :{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw new Error(data.detail||'请求失败');return data as T};
function Login({onLogin}:{onLogin:(token:string)=>void}){const [error,setError]=useState('');const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await request<{token:string}>('/api/login',null,'POST',{username:f.get('username'),password:f.get('password')});onLogin(r.token)}catch(x){setError((x as Error).message)}};return <main className="grid min-h-screen place-items-center bg-surface-2 p-4"><Card className="w-full max-w-md p-8"><Badge tone="brand">本地离线工程计算</Badge><h1 className="mt-4 text-3xl font-bold tracking-tight">规范公式计算平台</h1><p className="mt-2 text-sm text-muted">规范资料、计算快照与审核记录均保存在本机。</p><form className="mt-7 grid gap-4" onSubmit={submit}><Field label="用户名"><Input name="username" defaultValue="user" required/></Field><Field label="密码"><Input name="password" type="password" defaultValue="user123" required/></Field><Button size="lg">进入工作台</Button></form>{error&&<p className="mt-4 rounded-lg bg-danger/10 p-3 text-sm text-danger">{error}</p>}<p className="mt-5 text-xs text-muted">演示账号：admin / admin123；user / user123</p></Card></main>}
function Layout({user,children,onAdminLogin,onReturnUser}:{user:User;children:ReactNode;onAdminLogin:()=>void;onReturnUser:()=>void}){const links:Array<{to:string;Icon:LucideIcon;label:string}>=user.role==='admin'?[{to:'/',Icon:FolderKanban,label:'工作台'},{to:'/calculator',Icon:Calculator,label:'工程计算'},{to:'/standards',Icon:BookOpen,label:'规范库'},{to:'/review',Icon:ClipboardCheck,label:'审核发布'},{to:'/ocr',Icon:FileSearch,label:'OCR 资料'}]:[];return <div className={`min-h-screen ${user.role==='admin'?'admin-mode':'user-mode'}`}><header className="sticky top-0 z-20 border-b border-border/70 bg-bg/85 backdrop-blur-xl"><nav className="container-page flex h-16 items-center justify-between gap-4"><NavLink to={user.role==='admin'?'/':'/calculator'} className="flex shrink-0 items-center gap-2.5"><span className="grid h-9 min-w-[126px] place-items-center rounded-xl bg-brand px-3 text-[11px] font-extrabold tracking-tight text-brand-fg whitespace-nowrap">JTS 144-1-2010</span><span className="hidden text-lg font-extrabold tracking-tight sm:inline">规范<span className="text-brand">计算</span></span></NavLink>{user.role==='admin'&&<div className="hidden items-center gap-1 md:flex">{links.map(({to,label})=><NavLink key={to} to={to} end={to==='/'} className={({isActive})=>`rounded-lg px-3 py-2 text-sm font-medium transition ${isActive?'bg-surface-2 text-fg':'text-muted hover:text-fg'}`}>{label}</NavLink>)}</div>}<div className="flex items-center gap-2">{user.role==='admin'?<Button variant="outline" size="sm" onClick={onReturnUser}><LogOut size={15}/>返回用户界面</Button>:<Button variant="outline" size="sm" onClick={onAdminLogin}><ClipboardCheck size={15}/>管理员登录</Button>}</div></nav>{user.role==='admin'&&<div className="container-page flex gap-1 overflow-auto border-t border-border/50 py-2 md:hidden">{links.map(({to,label})=><NavLink key={to} to={to} end={to==='/'} className={({isActive})=>`whitespace-nowrap rounded-lg px-3 py-2 text-sm ${isActive?'bg-surface-2 text-fg':'text-muted'}`}>{label}</NavLink>)}</div>}</header><main className="container-page py-12">{children}</main></div>}
function Home({token}:{token:string}){const [stats,setStats]=useState<Stats|null>(null);const [formulas,setFormulas]=useState<Formula[]>([]);useEffect(()=>{void Promise.all([request<Stats>('/api/dashboard',token),request<{items:Formula[]}>('/api/catalog',token)]).then(([s,f])=>{setStats(s);setFormulas(f.items)})},[token]);const cards=[['已发布公式',stats?.published],['待审核草稿',stats?.drafts],['OCR 页面',stats?.ocr_pages],['计算快照',stats?.calculations]];return <div className="space-y-6"><section><Badge tone="brand">工程工作台</Badge><h1 className="mt-3 text-3xl font-bold tracking-tight">规范、公式与项目计算在同一条审计链上</h1><p className="mt-2 max-w-2xl text-sm text-muted">以规范条文为依据，使用已发布公式完成计算，并保留输入、版本和执行过程。</p></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label,value])=><Card key={label} className="p-5"><p className="text-xs uppercase tracking-wide text-muted">{label}</p><b className="mt-2 block text-3xl">{value??'—'}</b><p className="mt-2 text-xs text-muted">本地数据库实时统计</p></Card>)}</section><Card className="max-w-xl p-5"><div className="flex items-center justify-between"><div><Badge tone="brand">已发布规则</Badge><h2 className="mt-2 text-base font-bold">{formulas.length} 条规则可用于项目计算</h2><p className="mt-1 text-xs text-muted">当前覆盖第 10.2.1 条系缆力及三向分力。</p></div><NavLink className="text-sm font-semibold text-brand" to="/calculator">进入计算 →</NavLink></div></Card></div>}
function CalculatorPage({token}:{token:string}){const [formulas,setFormulas]=useState<Formula[]>([]);const [selected,setSelected]=useState<number[]>([]);const [values,setValues]=useState<Record<string,string>>({K:'1.3',n:'4',Fx:'600',Fy:'300',alpha:'30',beta:'15'});const [result,setResult]=useState<Record<string,{name:string;value:number;unit:string;citation:string;version:number}>|null>(null);const [error,setError]=useState('');useEffect(()=>{void request<{items:Formula[]}>('/api/catalog',token).then(x=>{setFormulas(x.items);setSelected(x.items.map(f=>f.id))})},[token]);const active=useMemo(()=>formulas.filter(f=>selected.includes(f.id)),[formulas,selected]);const variables=useMemo(()=>[...new Map(active.flatMap(f=>f.variables.map(v=>[v.code,v]))).values()], [active]);const calculate=async(e:FormEvent)=>{e.preventDefault();try{const r=await request<{outputs:Record<string,{name:string;value:number;unit:string;citation:string;version:number}>}>('/api/calculate',token,'POST',{formula_ids:selected,inputs:Object.fromEntries(Object.entries(values).map(([k,v])=>[k,Number(v)]))});setResult(r.outputs);setError('')}catch(x){setError((x as Error).message)}};return <div><header className="mb-6"><Badge tone="brand">OpenMEP CalculatorPage 模式 · 已适配</Badge><h1 className="mt-3 text-3xl font-bold">系缆力计算工况</h1><p className="mt-2 text-sm text-muted">选择已发布公式，系统合并必要参数并将结果版本固定到计算记录。</p></header><div className="grid gap-5 xl:grid-cols-[250px_minmax(320px,1fr)_minmax(280px,.85fr)]"><Card className="p-5"><h2 className="font-bold">公式包</h2><div className="mt-3 divide-y divide-border">{formulas.map(f=><label className="flex cursor-pointer gap-3 py-3 text-sm" key={f.id}><input className="mt-1 accent-brand" type="checkbox" checked={selected.includes(f.id)} onChange={()=>setSelected(s=>s.includes(f.id)?s.filter(id=>id!==f.id):[...s,f.id])}/><span><b className="formula-code text-brand">{f.code}</b><small className="mt-1 block text-muted">{f.name} · v{f.version}</small></span></label>)}</div></Card><Card className="p-6"><h2 className="font-bold">必要参数</h2><p className="mt-1 text-xs text-muted">输入值将随计算结果一并保存。</p><form className="mt-5 grid gap-4 sm:grid-cols-2" onSubmit={calculate}>{variables.map(v=><Field key={v.code} label={v.label||v.code} hint={`${v.code} · ${v.unit||'-'}`}><Input type="number" step="any" value={values[v.code]||''} onChange={e=>setValues({...values,[v.code]:e.target.value})}/></Field>)}<Button className="sm:col-span-2" size="lg"><Calculator size={17}/>执行计算</Button></form>{error&&<p className="mt-4 rounded-xl bg-danger/10 p-3 text-sm text-danger">{error}</p>}</Card><Card className="p-6"><h2 className="font-bold">计算结果</h2>{!result?<div className="mt-4 grid min-h-72 place-items-center rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted">输入必要参数后执行计算<br/>结果将附带公式版本和条文出处。</div>:<div className="mt-4 space-y-3">{Object.entries(result).map(([code,v])=><div className="rounded-xl border border-success/20 bg-success/5 p-4" key={code}><b className="formula-code text-xs text-success">{code} · {v.name}</b><strong className="mt-2 block text-2xl text-success">{v.value.toFixed(2)} <small className="text-sm font-medium">{v.unit}</small></strong><small className="mt-2 block text-xs text-muted">{v.citation} · v{v.version}</small></div>)}</div>}</Card></div></div>}
function CalculationArchive({token,isAdmin,refreshKey}:{token:string;isAdmin:boolean;refreshKey?:unknown}){type RecordItem={id:number;requested_formula_ids_json:string;input_json:string;created_at:string};const [records,setRecords]=useState<RecordItem[]>([]);const [cases,setCases]=useState<Array<{id:number;name:string;created_at:string}>>([]);const [note,setNote]=useState('');const [notes,setNotes]=useState<Array<{id:number;note:string;inputs:Record<string,number>}>>([]);const load=async()=>{const [r,c]=await Promise.all([request<{items:RecordItem[]}>('/api/records',token),request<{items:Array<{id:number;name:string;created_at:string}>}>('/api/calculation-cases',token)]);setRecords(r.items);setCases(c.items);const latest=r.items[0];if(isAdmin&&latest){const id=JSON.parse(latest.requested_formula_ids_json)[0];request<{items:Array<{id:number;note:string;inputs:Record<string,number>}>}>(`/api/admin/formulas/${id}/debug-notes`,token).then(x=>setNotes(x.items))}};useEffect(()=>{void load()},[token,isAdmin,refreshKey]);const latest=records[0];const save=async()=>{if(!latest)return;await request('/api/calculation-cases',token,'POST',{name:`计算案例 #${latest.id}`,formula_ids:JSON.parse(latest.requested_formula_ids_json),inputs:JSON.parse(latest.input_json)});await load()};const addNote=async()=>{if(!latest||!note.trim())return;const formulaId=JSON.parse(latest.requested_formula_ids_json)[0];await request(`/api/admin/formulas/${formulaId}/debug-notes`,token,'POST',{inputs:JSON.parse(latest.input_json),note});setNote('');await load()};return <section className="mt-8 grid gap-5 lg:grid-cols-2"><Card className="p-6"><div className="flex items-start justify-between gap-4"><div><Badge tone="brand">计算案例区</Badge><h2 className="mt-3 font-bold">保存与回放已计算的参数组</h2><p className="mt-1 text-sm text-muted">点击保存，会将最近一次计算使用的公式和全部输入参数固化为一个案例。</p></div><Button variant="outline" size="sm" onClick={()=>void load()}>刷新</Button></div><div className="mt-5 rounded-xl bg-surface-2 p-4 text-sm">{latest?<><b>最近计算 #{latest.id}</b><p className="mt-1 text-xs text-muted">{latest.created_at} · {Object.keys(JSON.parse(latest.input_json)).length} 个输入参数</p><Button className="mt-4" size="sm" onClick={()=>void save()}>保存为计算案例</Button></>:<span className="text-muted">请先在上方执行一次计算。</span>}</div>{cases.length>0&&<div className="mt-4 text-xs text-muted">已保存：{cases.slice(0,3).map(c=>c.name).join('、')}</div>}</Card>{isAdmin&&<Card className="p-6"><Badge tone="warn">备注区 · 管理员</Badge><h2 className="mt-3 font-bold">调试参数与公式备注</h2><p className="mt-1 text-sm text-muted">备注将与最近一次计算的第一条公式及其参数组一同保存，便于后续验算。</p><textarea className="mt-4 min-h-24 w-full rounded-xl border border-border bg-surface p-3 text-sm outline-none focus:border-brand" placeholder="记录本次调试结论、异常原因或待核对条文…" value={note} onChange={e=>setNote(e.target.value)}/><Button className="mt-3" size="sm" onClick={()=>void addNote()}>保存调试备注</Button>{notes.length>0&&<div className="mt-4 space-y-2">{notes.slice(0,2).map(n=><div className="rounded-lg bg-surface-2 p-3 text-xs" key={n.id}>{n.note}</div>)}</div>}</Card>}</section>}
function SketchCalculator({token,isAdmin}:{token:string;isAdmin:boolean}){const [formulas,setFormulas]=useState<Formula[]>([]);const [selected,setSelected]=useState<number[]>([]);const [focusId,setFocusId]=useState<number|null>(null);const [values,setValues]=useState<Record<string,string>>({K:'1.3',n:'4',Fx:'600',Fy:'300',alpha:'30',beta:'15'});const [result,setResult]=useState<Record<string,{name:string;value:number;unit:string;citation:string;version:number}>|null>(null);const [error,setError]=useState('');useEffect(()=>{void request<{items:Formula[]}>('/api/catalog',token).then(x=>{setFormulas(x.items);setSelected(x.items.map(f=>f.id));setFocusId(x.items[0]?.id||null)})},[token]);const focus=formulas.find(f=>f.id===focusId)||formulas[0];const active=formulas.filter(f=>selected.includes(f.id));const variables=useMemo(()=>[...new Map(active.flatMap(f=>f.variables.map(v=>[v.code,v]))).values()],[active]);const range=(code:string)=>code==='n'?[2,8,1]:code==='alpha'?[1,89,1]:code==='beta'?[0,45,1]:code==='K'?[1,2,.05]:[0,2000,10];const calculate=async(e:FormEvent)=>{e.preventDefault();try{const data=await request<{outputs:Record<string,{name:string;value:number;unit:string;citation:string;version:number}>}>('/api/calculate',token,'POST',{formula_ids:selected,inputs:Object.fromEntries(Object.entries(values).map(([key,value])=>[key,Number(value)]))});setResult(data.outputs);setError('')}catch(x){setError((x as Error).message)}};const page=focus?.page_number||30;return <><header className="mb-6"><Badge tone="brand">项目计算</Badge><h1 className="mt-3 text-3xl font-bold">系缆力计算工况</h1><p className="mt-2 text-sm text-muted">按规范原文核对公式，输入必要参数后计算；每次成功计算都会产生可保存的本地快照。</p></header><section className="grid items-start gap-6 xl:grid-cols-2"><div className="space-y-5"><Card className="p-6"><Badge tone="brand">选择公式功能框</Badge><h2 className="mt-3 font-bold">选择要参与本次计算的公式</h2><div className="mt-4 grid gap-2">{formulas.map(f=><label className={`flex cursor-pointer items-center gap-3 rounded-xl border p-3 text-sm ${focus?.id===f.id?'border-brand bg-brand/5':'border-border'}`} key={f.id}><input className="accent-brand" type="checkbox" checked={selected.includes(f.id)} onChange={()=>setSelected(s=>s.includes(f.id)?s.filter(id=>id!==f.id):[...s,f.id])}/><button type="button" onClick={()=>setFocusId(f.id)} className="min-w-0 flex-1 text-left"><b className="formula-code text-brand">{f.code}</b><span className="ml-2">{f.name}</span></button></label>)}</div></Card><Card className="p-6"><div className="flex items-start justify-between gap-4"><div><Badge tone="brand">规范原文 PDF</Badge><h2 className="mt-3 font-bold">{focus?.citation||'选择公式查看出处'}</h2><p className="mt-1 text-sm text-muted">原文页随公式选择切换；点击图片可在新页查看原始分辨率。</p></div><span className="text-xs text-muted">PDF 第 {page} 页</span></div><a className="mt-4 block max-h-[620px] overflow-auto rounded-xl bg-surface-2 p-4" href={`/ocr-files/pages/page_${String(page).padStart(3,'0')}.png`} target="_blank" rel="noreferrer"><img className="pdf-page mx-auto max-w-full" src={`/ocr-files/pages/page_${String(page).padStart(3,'0')}.png`} alt={`规范 PDF 第 ${page} 页`}/></a></Card></div><div className="space-y-5"><Card className="p-6"><Badge tone="brand">必要参数输入框</Badge><h2 className="mt-3 font-bold">参数输入</h2><p className="mt-1 text-sm text-muted">数值框与滑块双向同步；超出滑块建议范围时保留输入值，便于工程人员精确取值。</p><form className="mt-5 space-y-3" onSubmit={calculate}>{variables.map(v=>{const [min,max,step]=range(v.code);const raw=values[v.code]||'';const slider=Math.min(max,Math.max(min,Number(raw)||min));return <div className="rounded-xl border border-border p-3" key={v.code}><div className="grid grid-cols-[1fr_112px] items-center gap-3"><label className="text-sm font-medium">{v.label||v.code}<small className="mt-1 block text-xs font-normal text-muted">{v.code} · {v.unit||'-'}</small></label><Input type="number" step="any" value={raw} onChange={e=>setValues(s=>({...s,[v.code]:e.target.value}))}/></div><input className="mt-3 w-full accent-brand" type="range" min={min} max={max} step={step} value={slider} onChange={e=>setValues(s=>({...s,[v.code]:e.target.value}))}/></div>})}<Button className="w-full" size="lg"><Calculator size={17}/>开始计算并保存结果</Button></form>{error&&<p className="mt-4 rounded-xl bg-danger/10 p-3 text-sm text-danger">{error}</p>}</Card><Card className="p-6"><Badge tone="brand">计算结果</Badge>{!result?<div className="mt-4 grid min-h-52 place-items-center rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted">完成参数输入后点击“开始计算”，结果会在此展示。</div>:<><div className="mt-4 rounded-xl border-l-4 border-brand bg-brand/5 p-5"><span className="text-sm font-semibold text-brand">最终合力 N</span><strong className="mt-2 block text-4xl text-brand">{Object.values(result)[0]?.value.toFixed(2)} <small className="text-base font-medium">kN</small></strong><small className="mt-2 block text-xs text-muted">{Object.values(result)[0]?.citation} · v{Object.values(result)[0]?.version}</small></div><div className="mt-4 grid grid-cols-3 gap-2">{Object.entries(result).slice(1).map(([code,v])=><div className="rounded-xl border border-border bg-surface-2 p-3" key={code}><span className="formula-code text-xs text-muted">{code}</span><b className="mt-1 block text-lg">{v.value.toFixed(2)}</b><small className="text-xs text-muted">{v.unit}</small></div>)}</div><ForceDiagram values={result}/></>}</Card></div></section><CalculationArchive token={token} isAdmin={isAdmin}/></>}
function CalculatorWorkspace({token,isAdmin}:{token:string;isAdmin:boolean}){return <SearchableCalculator token={token} isAdmin={isAdmin}/>}
function ForceDiagram({values}:{values:Record<string,{value:number}>}){const list=Object.values(values);const n=list[0]?.value||0;const nx=list[1]?.value||0;const ny=list[2]?.value||0;const nz=list[3]?.value||0;const scale=Math.max(n,1);const x=150+100*nx/scale,y=170-72*ny/scale,z=170+55*nz/scale;return <svg viewBox="0 0 360 250" className="mt-5 w-full rounded-xl border border-border bg-surface-2" role="img" aria-label="系缆力分量示意图"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8z" fill="#1d7a69"/></marker></defs><line x1="150" y1="170" x2={x} y2="170" stroke="#6e8795" strokeWidth="2" strokeDasharray="5 4"/><line x1={x} y1="170" x2={x} y2={y} stroke="#6e8795" strokeWidth="2" strokeDasharray="5 4"/><line x1="150" y1="170" x2={x} y2={z} stroke="#1d7a69" strokeWidth="4" markerEnd="url(#arr)"/><text x="155" y="192" fill="#637789" fontSize="12">原点</text><text x={x+7} y="188" fill="#637789" fontSize="12">Nx</text><text x={x+7} y={y-7} fill="#637789" fontSize="12">Ny</text><text x={x+7} y={z-8} fill="#1d7a69" fontSize="13" fontWeight="700">合力 N</text><text x="16" y="28" fill="#637789" fontSize="12">Nx {nx.toFixed(1)} · Ny {ny.toFixed(1)} · Nz {nz.toFixed(1)} kN</text></svg>}
function CalculatorWorkbench({token}:{token:string}){const [formulas,setFormulas]=useState<Formula[]>([]);const [selected,setSelected]=useState<number[]>([]);const [values,setValues]=useState<Record<string,string>>({K:'1.3',n:'4',Fx:'600',Fy:'300',alpha:'30',beta:'15'});const [result,setResult]=useState<Record<string,{name:string;value:number;unit:string;citation:string;version:number}>|null>(null);const [error,setError]=useState('');useEffect(()=>{void request<{items:Formula[]}>('/api/catalog',token).then(x=>{setFormulas(x.items);setSelected(x.items.map(f=>f.id))})},[token]);const active=useMemo(()=>formulas.filter(f=>selected.includes(f.id)),[formulas,selected]);const variables=useMemo(()=>[...new Map(active.flatMap(f=>f.variables.map(v=>[v.code,v]))).values()], [active]);const setValue=(key:string,value:string)=>setValues(s=>({...s,[key]:value}));const calculate=async(e:FormEvent)=>{e.preventDefault();try{const r=await request<{outputs:Record<string,{name:string;value:number;unit:string;citation:string;version:number}>}>('/api/calculate',token,'POST',{formula_ids:selected,inputs:Object.fromEntries(Object.entries(values).map(([k,v])=>[k,Number(v)]))});setResult(r.outputs);setError('')}catch(x){setError((x as Error).message)}};const range=(code:string)=>code==='n'?[2,8,1]:code==='alpha'?[1,89,1]:code==='beta'?[0,45,1]:code==='K'?[1,2,.05]:[0,2000,10];return <div><header className="mb-6"><Badge tone="brand">系缆力计算 · Demo 交互模式</Badge><h1 className="mt-3 text-3xl font-bold">系缆力计算工况</h1><p className="mt-2 text-sm text-muted">通过数值框或滑块设定工况；执行后保存规范版本、输入与结果快照。</p></header><div className="grid gap-5 xl:grid-cols-[230px_minmax(360px,1fr)_minmax(310px,.9fr)]"><Card className="p-5"><h2 className="font-bold">公式包</h2><div className="mt-3 divide-y divide-border">{formulas.map(f=><label className="flex cursor-pointer gap-3 py-3 text-sm" key={f.id}><input className="mt-1 accent-brand" type="checkbox" checked={selected.includes(f.id)} onChange={()=>setSelected(s=>s.includes(f.id)?s.filter(id=>id!==f.id):[...s,f.id])}/><span><b className="formula-code text-brand">{f.code}</b><small className="mt-1 block text-muted">{f.name} · v{f.version}</small></span></label>)}</div></Card><Card className="p-6"><h2 className="font-bold">输入工况</h2><p className="mt-1 text-xs text-muted">参数范围来自当前演示工况；数字框可精确输入。</p><form className="mt-5 space-y-3" onSubmit={calculate}>{variables.map(v=>{const [min,max,step]=range(v.code);return <div className="rounded-xl border border-border p-3" key={v.code}><div className="grid grid-cols-[1fr_100px] items-center gap-3"><label className="text-sm font-medium">{v.label||v.code}<small className="mt-1 block text-xs font-normal text-muted">{v.code} · {v.unit||'-'}</small></label><Input type="number" min={min} max={max} step={step} value={values[v.code]||''} onChange={e=>setValue(v.code,e.target.value)}/></div><input className="mt-3 w-full accent-brand" type="range" min={min} max={max} step={step} value={values[v.code]||min} onChange={e=>setValue(v.code,e.target.value)}/></div>})}<Button className="w-full" size="lg"><Calculator size={17}/>开始计算并写入记录</Button></form>{error&&<p className="mt-4 rounded-xl bg-danger/10 p-3 text-sm text-danger">{error}</p>}</Card><Card className="p-6"><h2 className="font-bold">计算结果</h2>{!result?<div className="mt-4 grid min-h-72 place-items-center rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted">输入工况后开始计算。<br/>合力、分量与规范版本会在此显示。</div>:<><div className="mt-4 rounded-xl border-l-4 border-brand bg-brand/5 p-5"><span className="text-sm font-semibold text-brand">最终合力 N</span><strong className="mt-2 block text-4xl text-brand">{Object.values(result)[0]?.value.toFixed(2)} <small className="text-base font-medium">kN</small></strong><small className="mt-2 block text-xs text-muted">{Object.values(result)[0]?.citation} · v{Object.values(result)[0]?.version}</small></div><div className="mt-4 grid grid-cols-3 gap-2">{Object.entries(result).slice(1).map(([code,v])=><div className="rounded-xl border border-border bg-surface-2 p-3" key={code}><span className="formula-code text-xs text-muted">{code}</span><b className="mt-1 block text-lg">{v.value.toFixed(2)}</b><small className="text-xs text-muted">{v.unit}</small></div>)}</div><ForceDiagram values={result}/></>}</Card></div></div>}
function Standards({token}:{token:string}){type Chapter={id:number;number:string;title:string;formula_count:number};type Standard={chapters:Chapter[]};const [items,setItems]=useState<Formula[]>([]);const [chapters,setChapters]=useState<Chapter[]>([]);const [selectedChapterId,setSelectedChapterId]=useState<number|null>(null);const [current,setCurrent]=useState<Formula|null>(null);useEffect(()=>{void Promise.all([request<{items:Formula[]}>('/api/catalog',token),request<{items:Standard[]}>('/api/standards',token)]).then(([catalog,tree])=>{setItems(catalog.items);const availableChapters=tree.items[0]?.chapters||[];setChapters(availableChapters);setSelectedChapterId(availableChapters[0]?.id||null)})},[token]);const visibleItems=useMemo(()=>items.filter(item=>item.chapter_id===selectedChapterId),[items,selectedChapterId]);const selectedChapter=chapters.find(chapter=>chapter.id===selectedChapterId);useEffect(()=>{setCurrent(visibleItems[0]||null)},[visibleItems]);return <div><header className="mb-6 grid gap-4 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-end"><div><Badge tone="brand">规范规则库</Badge><h1 className="mt-3 text-3xl font-bold">{selectedChapter?selectedChapter.number+' · '+selectedChapter.title:'规范章节'}</h1></div><select aria-label="选择章节" className="h-10 min-w-64 rounded-xl border border-border bg-surface px-3 text-sm text-fg" value={selectedChapterId||''} onChange={event=>setSelectedChapterId(Number(event.target.value))}>{chapters.map(chapter=><option key={chapter.id} value={chapter.id}>{chapter.number} · {chapter.title}（{chapter.formula_count} 条公式）</option>)}</select></header><div className="grid gap-5 lg:grid-cols-[290px_1fr]"><Card className="overflow-hidden p-0">{visibleItems.map(f=><button key={f.id} onClick={()=>setCurrent(f)} className={"block w-full border-b border-border px-5 py-4 text-left hover:bg-surface-2 "+(current?.id===f.id?'bg-surface-2':'')}><b className="formula-code text-sm text-brand">{f.code}</b><span className="mt-1 block text-sm">{f.name}</span><small className="mt-1 block text-xs text-muted">已发布 v{f.version}</small></button>)}</Card><Card className="p-7">{current&&<><div className="flex justify-between gap-4"><div><Badge tone="success">已发布 v{current.version}</Badge><h2 className="mt-3 text-2xl font-bold">{current.name}</h2></div></div><div className="mt-7 overflow-auto rounded-xl border border-brand/20 bg-brand/5 p-5"><p className="mb-3 text-xs font-semibold uppercase tracking-wide text-muted">易读公式</p><div className="formula-viewport"><LatexFormula latex={current.latex}/></div><details className="mt-4"><summary className="cursor-pointer text-xs text-muted">查看原始 LaTeX</summary><pre className="formula-code mt-2 whitespace-pre-wrap text-xs text-muted">{current.latex}</pre></details></div><dl className="mt-6 grid gap-4 border-t border-border pt-5 text-sm sm:grid-cols-2"><div><dt className="text-xs text-muted">规范出处</dt><dd className="mt-1">{current.citation} · PDF 第 {current.page_number||'—'} 页</dd></div><div><dt className="text-xs text-muted">必要参数</dt><dd className="mt-1">{current.variables.map(v=>(v.label||v.code)+'（'+(v.unit||'-')+'）').join('、')}</dd></div></dl></>}</Card></div></div>}
function Review({token,ocr}:{token:string;ocr:boolean}){const [items,setItems]=useState<Formula[]>([]);const [pages,setPages]=useState<OcrAsset[]>([]);const [page,setPage]=useState<OcrPage|null>(null);const openPage=(pageNumber:number)=>void request<OcrPage>(`/api/ocr-assets/${pageNumber}`,token).then(setPage);useEffect(()=>{if(ocr){void request<{items:OcrAsset[]}>('/api/ocr-assets',token).then(x=>{setPages(x.items);if(x.items[0])openPage(x.items[0].page_number)})}else void request<{items:Formula[]}>('/api/admin/catalog',token).then(x=>setItems(x.items))},[token,ocr]);if(!ocr)return <div><Badge tone="warn">发布控制</Badge><h1 className="mt-3 text-3xl font-bold">审核与发布队列</h1><Card className="mt-6 overflow-hidden p-0"><table><thead><tr><th>公式</th><th>版本</th><th>状态</th><th>出处</th></tr></thead><tbody>{items.map(f=><tr key={f.id}><td><b className="formula-code text-brand">{f.code}</b> · {f.name}</td><td>v{f.version}</td><td><Badge tone="success">{f.status}</Badge></td><td>{f.citation}</td></tr>)}</tbody></table></Card></div>;return <div><Badge tone="warn">待审核资料库</Badge><h1 className="mt-3 text-3xl font-bold">OCR 审核工作台</h1><div className="mt-6 grid gap-5 lg:grid-cols-[250px_1fr]"><Card className="grid max-h-[700px] grid-cols-4 content-start gap-2 overflow-auto p-3">{pages.map(p=><button key={p.id} onClick={()=>openPage(p.page_number)} className={`rounded-lg border p-2 text-xs ${page?.page_number===p.page_number?'border-brand bg-brand/10 text-brand':'border-border text-muted'}`}>{p.page_number}</button>)}</Card><Card className="p-5">{page&&<><div className="flex justify-between"><div><h2 className="font-bold">PDF 第 {page.page_number} 页</h2><p className="mt-1 text-xs text-muted">OCR 结果仅供审核，不会自动进入计算内核。</p></div><Badge tone="warn">draft_only</Badge></div><div className="mt-5 grid gap-5 xl:grid-cols-[minmax(360px,1fr)_300px]"><div className="bg-surface-2 p-4"><img className="pdf-page mx-auto max-h-[620px] max-w-full" src={`/ocr-files/${page.page_image}`} /></div><div className="max-h-[620px] overflow-auto"><h3 className="font-bold">文字与公式候选</h3>{page.formulas.map(f=><div className="mt-3 rounded-xl border border-border p-3 text-xs" key={f.id}><Badge tone={f.confirmed?'success':'warn'}>{f.confirmed?'已确认':'待转写'}</Badge><pre className="mt-2 whitespace-pre-wrap text-muted">{f.recognized_latex||'未转写 LaTeX'}</pre></div>)}{page.blocks.slice(0,40).map(b=><p className="mt-2 rounded-lg bg-surface-2 p-2 text-xs text-muted" key={b.id}>#{b.sequence} {b.corrected_text||b.raw_text}</p>)}</div></div></>}</Card></div></div>}

type ReviewDraft={standard_id:number;chapter_id:number|null;code:string;name:string;citation:string;page_number:number;latex:string;substitution_latex:string;expression:string;result_key:string;variables:string;dependencies:string;conditions:string;table:string;source_crop_path:string;example_inputs:string;expected:string;tolerance:string};
const emptyDraft:ReviewDraft={standard_id:1,chapter_id:null,code:'',name:'',citation:'',page_number:1,latex:'',substitution_latex:'',expression:'',result_key:'',variables:'[]',dependencies:'',conditions:'[]',table:'',source_crop_path:'',example_inputs:'{}',expected:'0',tolerance:'0.0001'};
function AdminReview({token}:{token:string}){
  const [items,setItems]=useState<Formula[]>([]);const [ocrDrafts,setOcrDrafts]=useState<OcrFormulaDraft[]>([]);const [selectedId,setSelectedId]=useState<number|null>(null);const [draft,setDraft]=useState<ReviewDraft>(emptyDraft);const [related,setRelated]=useState<Array<{code:string;name:string;direction:string;status:string;version:number}>>([]);const [notice,setNotice]=useState('');const [validation,setValidation]=useState('');
  const load=async()=>{const [data,ocr]=await Promise.all([request<{items:Formula[]}>('/api/admin/catalog',token),request<{items:OcrFormulaDraft[]}>('/api/admin/ocr-formula-drafts',token)]);setItems(data.items);setOcrDrafts(ocr.items);setSelectedId(current=>data.items.some(item=>item.id===current)?current:data.items[0]?.id||null)};
  useEffect(()=>{void load()},[token]);
  useEffect(()=>{if(!selectedId)return;void Promise.all([request<Formula & {standard_id:number;chapter_id:number|null;example:Record<string,unknown>}>(`/api/admin/formulas/${selectedId}/versions/${items.find(item=>item.id===selectedId)?.version_id}`,token),request<{items:Array<{code:string;name:string;direction:string;status:string;version:number}>}>(`/api/admin/formulas/${selectedId}/related`,token)]).then(([detail,links])=>{setRelated(links.items);setDraft({standard_id:detail.standard_id,chapter_id:detail.chapter_id,code:detail.code,name:detail.name,citation:detail.citation,page_number:detail.page_number||1,latex:detail.latex,substitution_latex:detail.rule.substitution_latex||'',expression:detail.rule.expression||'',result_key:detail.rule.result_key||'',variables:JSON.stringify(detail.variables,null,2),dependencies:detail.dependencies.join(', '),conditions:JSON.stringify(detail.rule.conditions||[],null,2),table:detail.rule.table?JSON.stringify(detail.rule.table,null,2):'',source_crop_path:detail.rule.source_crop_path||'',example_inputs:JSON.stringify(detail.example.inputs||{},null,2),expected:String(detail.example.expected??''),tolerance:String(detail.example.tolerance??0.0001)})}).catch(error=>setNotice((error as Error).message))},[selectedId,items,token]);
  const change=(key:keyof ReviewDraft,value:string)=>setDraft(current=>({...current,[key]:key==='page_number'||key==='standard_id'?Number(value):value}));
  const useOcrDraft=(candidate:OcrFormulaDraft)=>{setSelectedId(null);setRelated([]);setDraft({...emptyDraft,code:candidate.suggested_code,name:'待人工命名',citation:`JTS 144-1-2010（原文右侧编号 OCR：${candidate.raw_formula_label}）`,page_number:candidate.page_number,latex:candidate.ocr_latex||'',source_crop_path:candidate.source_crop_path});setNotice(`已载入第 ${candidate.page_number} 页右侧编号 ${candidate.raw_formula_label||candidate.suggested_code} 的公式草稿。上下文：${candidate.article_context||'请以原文页为准'}。变量/条文候选：${candidate.variable_context.join('；')||'请在原图核对'}。OCR 数字可能有误，需补全 LaTeX、受限表达式、表格规则和验算后才能发布。`)};
  const payload=()=>{const conditions=JSON.parse(draft.conditions||'[]');const table=draft.table.trim()?JSON.parse(draft.table):undefined;return {standard_id:draft.standard_id,chapter_id:draft.chapter_id,code:draft.code.trim(),name:draft.name.trim(),citation:draft.citation.trim(),page_number:draft.page_number,latex:draft.latex.trim(),variables:JSON.parse(draft.variables),dependencies:draft.dependencies.split(',').map(item=>item.trim()).filter(Boolean),rule:{kind:table?(table.mode==='interpolation'?'interpolation':'lookup'):'expression',expression:draft.expression.trim(),result_key:draft.result_key.trim()||draft.code.trim(),conditions, ...(table?{table}:{ }), ...(draft.source_crop_path.trim()?{source_crop_path:draft.source_crop_path.trim()}: {}), ...(draft.substitution_latex.trim()?{substitution_latex:draft.substitution_latex.trim()}: {})},example:{inputs:JSON.parse(draft.example_inputs),expected:Number(draft.expected),tolerance:Number(draft.tolerance)}}};
  const save=async()=>{try{const body=payload();if(selectedId){const response=await request<{version_id:number}>(`/api/admin/formulas/${selectedId}`,token,'PUT',body);setNotice(`已生成草稿版本 #${response.version_id}；尚未发布。`)}else{const response=await request<{id:number}>('/api/admin/formulas',token,'POST',body);setSelectedId(response.id);setNotice('已创建草稿；尚未发布。')}await load()}catch(error){setNotice(`保存失败：${(error as Error).message}`)}};
  const latest=items.find(item=>item.id===selectedId);const action=async(kind:'submit'|'validate'|'publish')=>{if(!selectedId||!latest)return;try{const endpoint=`/api/admin/formulas/${selectedId}/versions/${latest.version_id}/${kind}`;if(kind==='publish'&&!window.confirm('确认发布？发布后此版本将立即进入用户前端。'))return;const response=await request<{passed?:boolean;actual?:number;expected?:number;status?:string}>(endpoint,token,'POST',kind==='submit'?{note:'人工审核提交'}:undefined);setValidation(kind==='validate'?`${response.passed?'验算通过':'验算失败'}：实际 ${response.actual}，预期 ${response.expected}`:`${kind==='submit'?'已提交审核':'已发布，用户前端将在下次目录同步时显示。'}`);await load()}catch(error){setValidation((error as Error).message)}};
  const tablePreview=(()=>{try{const table=draft.table.trim()?JSON.parse(draft.table) as {rows?:Array<Record<string,number>>}:{};return {rows:table.rows||[]}}catch{return {rows:[]}}})();const tableRows=tablePreview.rows;const readableVariables=(()=>{try{return JSON.parse(draft.variables) as Variable[]}catch{return []}})();const readableConditions=(()=>{try{return JSON.parse(draft.conditions) as Array<{expression:string;message?:string}>}catch{return []}})();const readableExample=(()=>{try{return JSON.parse(draft.example_inputs) as Record<string,unknown>}catch{return {}}})();const readableFormula=draft.substitution_latex.trim()||draft.latex.trim()||'尚未录入公式';
  return <div><Badge tone="warn">发布控制</Badge><h1 className="mt-3 text-3xl font-bold">公式审核与发布工作台</h1><p className="mt-2 text-sm text-muted">OCR 仅作待审核资料；保存为草稿、人工提交审核、验算通过并确认发布后，才进入用户前端。</p><div className="review-workbench mt-6 grid gap-5 xl:grid-cols-[240px_minmax(0,1fr)]"><Card className="flex h-full flex-col p-4"><Button className="w-full" variant="outline" onClick={()=>{setSelectedId(null);setDraft(emptyDraft);setRelated([]);setNotice('新建草稿')}}>新建公式草稿</Button><p className="mt-4 text-xs font-semibold text-muted">已保存公式草稿</p><div className="mt-2 min-h-0 flex-1 space-y-2 overflow-auto">{items.map(item=><button key={item.id} onClick={()=>setSelectedId(item.id)} className={`w-full rounded-xl border p-3 text-left text-sm ${item.id===selectedId?'border-brand bg-brand/5':'border-border'}`}><b className="formula-code text-brand">{item.code}</b><span className="mt-1 block"><FormulaText>{item.name}</FormulaText></span><small className="mt-1 block text-muted">v{item.version} · {item.status}</small></button>)}</div><details className="mt-4 rounded-xl border border-warn/30 bg-warn/5 p-3"><summary className="cursor-pointer text-sm font-semibold text-warn">OCR 待审核候选（{ocrDrafts.length}）</summary><p className="mt-2 text-xs leading-5 text-muted">系统已按页载入全文 OCR。候选可能是公式、表格值或误识别片段；点击后仅预填为可编辑草稿，绝不自动发布或执行。</p><div className="mt-3 max-h-96 space-y-2 overflow-auto">{ocrDrafts.map(candidate=><button type="button" key={candidate.id} onClick={()=>useOcrDraft(candidate)} className="w-full rounded-lg border border-border bg-surface p-3 text-left text-xs hover:border-warn"><b className="formula-code text-warn">{candidate.suggested_code||`第 ${candidate.page_number} 页 #${candidate.sequence}`}</b><span className="mt-1 block line-clamp-2 text-muted">{candidate.ocr_text||'OCR 未识别出可用文本'}</span></button>)}</div></details></Card><div className="grid items-stretch gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(440px,1.25fr)]"><Card className="p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><Badge tone="brand">独立转写与人工确认</Badge><h2 className="mt-3 font-bold">公式定义</h2></div>{latest&&<div className="flex gap-2"><Button variant="outline" size="sm" onClick={()=>void action('submit')}>提交审核</Button><Button variant="outline" size="sm" onClick={()=>void action('validate')}>验算</Button><Button size="sm" onClick={()=>void action('publish')}>确认发布</Button></div>}</div><div className="mt-5 grid gap-3 sm:grid-cols-2"><Field label="原文公式编号"><Input value={draft.code} onChange={e=>change('code',e.target.value)}/></Field><Field label="公式名称"><Input value={draft.name} onChange={e=>change('name',e.target.value)}/></Field><Field label="规范出处"><Input value={draft.citation} onChange={e=>change('citation',e.target.value)}/></Field><Field label="PDF 页码"><Input type="number" value={draft.page_number} onChange={e=>change('page_number',e.target.value)}/></Field></div><Field label="LaTeX（人工确认文本）"><textarea className="mt-1 min-h-24 w-full rounded-xl border border-border bg-surface p-3 font-mono text-sm" value={draft.latex} onChange={e=>change('latex',e.target.value)}/></Field><div className="mt-4 rounded-xl border border-border bg-surface-2 p-4"><p className="text-center text-sm font-semibold text-brand">LaTeX 编译预览</p><div className="formula-viewport mt-3"><LatexFormula latex={draft.latex||'\\text{等待人工录入 LaTeX}'}/></div></div></Card><Card className="p-6"><Badge tone="brand">原文 PDF 对照</Badge><h3 className="mt-3 font-bold">PDF 第 {draft.page_number} 页</h3><p className="mt-1 text-sm text-muted">此预览定位当前草稿所在页，可滚动查看完整规范。</p><div className="review-pdf-frame"><StandardPdfPreview page={draft.page_number}/></div></Card><Card className="p-6 xl:col-span-2"><Badge tone="brand">审核依据</Badge><h2 className="mt-3 font-bold">用工程语言核对这条公式</h2><p className="mt-1 text-sm text-muted">LaTeX 负责原文对照和显示；只有下方受限计算表达式或查表规则会进入计算内核。</p><div className="mt-5 rounded-xl border border-brand/20 bg-brand/5 p-5"><p className="text-xs font-semibold text-muted">计算关系</p><div className="formula-viewport mt-3"><LatexFormula latex={draft.latex||'\\text{等待人工录入 LaTeX}'}/></div><Field label="计算关系 LaTeX（与上方实时同步）"><textarea className="mt-1 min-h-24 w-full rounded-xl border border-border bg-surface p-3 font-mono text-sm" value={draft.latex} onChange={e=>change('latex',e.target.value)}/></Field><p className="mt-3 text-sm text-muted">结果：<b className="text-fg">{draft.result_key||draft.code||'待填写'}</b></p></div><div className="mt-5 grid gap-4 lg:grid-cols-2"><Field label="受限计算表达式（人工确认后才执行）"><Input value={draft.expression} onChange={e=>change('expression',e.target.value)} placeholder="只允许数学表达式和白名单函数"/></Field><Field label="结果参数名"><Input value={draft.result_key} onChange={e=>change('result_key',e.target.value)} placeholder="例如 N 或 C"/></Field></div><details className="mt-5 rounded-xl border border-border"><summary className="cursor-pointer px-4 py-3 text-sm font-semibold">查表 / 插值规则（如适用）</summary><div className="border-t border-border p-4"><p className="mb-3 text-sm text-muted">以 JSON 编辑查表或线性插值；保存后会在下方预览，确认发布后才进入内核。</p><textarea className="min-h-32 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.table} onChange={e=>change('table',e.target.value)} placeholder={'{"input":"x","output":"y","rows":[{"x":1,"y":2}]}'}/>{tablePreview?.rows&&<div className="mt-4 overflow-auto rounded-xl border border-border"><table><thead><tr>{Object.keys(tablePreview.rows[0]||{}).map(key=><th key={key}>{key}</th>)}</tr></thead><tbody>{tablePreview.rows.map((row,index)=><tr key={index}>{Object.values(row).map((value,column)=><td key={column}>{value}</td>)}</tr>)}</tbody></table></div>}</div></details><details className="mt-5 rounded-xl border border-border"><summary className="cursor-pointer px-4 py-3 text-sm font-semibold">参数、依赖、条件与验算</summary><div className="grid gap-4 border-t border-border p-4 lg:grid-cols-2"><Field label="参数 JSON"><textarea className="mt-1 min-h-40 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.variables} onChange={e=>change('variables',e.target.value)}/></Field><Field label="依赖公式编号（逗号分隔）"><Input value={draft.dependencies} onChange={e=>change('dependencies',e.target.value)} placeholder="例如 10.2.1-1, 10.2.1-2"/></Field><Field label="适用条件 JSON"><textarea className="mt-1 min-h-32 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.conditions} onChange={e=>change('conditions',e.target.value)} placeholder={'[{"expression":"x > 0","message":"原文限制"}]'}/></Field><Field label="验算输入 JSON"><textarea className="mt-1 min-h-24 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.example_inputs} onChange={e=>change('example_inputs',e.target.value)}/></Field><div className="grid grid-cols-2 gap-3"><Field label="预期结果"><Input value={draft.expected} onChange={e=>change('expected',e.target.value)}/></Field><Field label="容差"><Input value={draft.tolerance} onChange={e=>change('tolerance',e.target.value)}/></Field></div></div></details>{related.length>0&&<div className="mt-4 rounded-xl bg-surface-2 p-4"><b>与当前公式有关的已编号公式</b><div className="mt-2 flex flex-wrap gap-2">{related.map(item=><span key={`${item.code}-${item.direction}`} className="rounded-lg bg-surface px-3 py-2 text-sm"><b className="formula-code">{item.code}</b> · {item.name} <small className="text-muted">{item.direction==='selected'?'当前':item.direction==='dependency'?'引用':'被引用'} · {item.status}</small></span>)}</div></div>}<Button className="mt-5" onClick={()=>void save()}>保存草稿版本</Button>{notice&&<p className="mt-3 text-sm text-muted">{notice}</p>}{validation&&<p className="mt-2 text-sm font-medium text-brand">{validation}</p>}</Card></div></div></div>;
  return <div><Badge tone="warn">发布控制</Badge><h1 className="mt-3 text-3xl font-bold">公式审核与发布工作台</h1><p className="mt-2 text-sm text-muted">OCR 仅作待审核资料；保存为草稿、人工提交审核、验算通过并确认发布后，才进入用户前端。</p><div className="mt-6 grid gap-5 xl:grid-cols-[300px_1fr]"><Card className="p-4"><Button className="w-full" variant="outline" onClick={()=>{setSelectedId(null);setDraft(emptyDraft);setRelated([]);setNotice('新建草稿')}}>新建公式草稿</Button><div className="mt-4 space-y-2">{items.map(item=><button key={item.id} onClick={()=>setSelectedId(item.id)} className={`w-full rounded-xl border p-3 text-left text-sm ${item.id===selectedId?'border-brand bg-brand/5':'border-border'}`}><b className="formula-code text-brand">{item.code}</b><span className="mt-1 block"><FormulaText>{item.name}</FormulaText></span><small className="mt-1 block text-muted">v{item.version} · {item.status}</small></button>)}</div></Card><div className="space-y-5"><Card className="p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><Badge tone="brand">独立转写与人工确认</Badge><h2 className="mt-3 font-bold">公式定义</h2></div>{latest&&<div className="flex gap-2"><Button variant="outline" size="sm" onClick={()=>void action('submit')}>提交审核</Button><Button variant="outline" size="sm" onClick={()=>void action('validate')}>验算</Button><Button size="sm" onClick={()=>void action('publish')}>确认发布</Button></div>}</div><div className="mt-5 grid gap-3 sm:grid-cols-2"><Field label="原文公式编号"><Input value={draft.code} onChange={e=>change('code',e.target.value)}/></Field><Field label="公式名称"><Input value={draft.name} onChange={e=>change('name',e.target.value)}/></Field><Field label="规范出处"><Input value={draft.citation} onChange={e=>change('citation',e.target.value)}/></Field><Field label="PDF 页码"><Input type="number" value={draft.page_number} onChange={e=>change('page_number',e.target.value)}/></Field></div><Field label="LaTeX（人工确认文本）"><textarea className="mt-1 min-h-24 w-full rounded-xl border border-border bg-surface p-3 font-mono text-sm" value={draft.latex} onChange={e=>change('latex',e.target.value)}/></Field><div className="mt-4 rounded-xl border border-border bg-surface-2 p-4"><p className="text-center text-sm font-semibold text-brand">LaTeX 编译预览</p><div className="formula-viewport mt-3"><LatexFormula latex={draft.latex||'\\text{等待人工录入 LaTeX}'}/></div></div></Card><Card className="p-6"><Badge tone="brand">审核依据</Badge><h2 className="mt-3 font-bold">用工程语言核对这条公式</h2><p className="mt-1 text-sm text-muted">审核时先看公式含义、参数、适用条件和验算结果；系统内部如何执行由下方实现细节负责。</p><div className="mt-5 space-y-4"><div className="rounded-xl border border-brand/20 bg-brand/5 p-5"><p className="text-xs font-semibold text-muted">计算关系</p><div className="formula-viewport mt-3 overflow-auto"><LatexFormula latex={readableFormula}/></div><p className="mt-3 text-sm text-muted">结果：<b className="text-fg">{draft.result_key||draft.code||'待填写'}</b></p></div><div><p className="text-xs font-semibold text-muted">参数含义</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{readableVariables.length?readableVariables.map(variable=><div className="rounded-lg bg-surface-2 px-3 py-2 text-sm" key={variable.code}><b><ParameterLabel variable={variable}/></b><span className="ml-2 text-muted">{variable.label||'未填写含义'} · {variable.unit||'无单位'}</span></div>):<p className="text-sm text-muted">尚未填写参数。</p>}</div></div><div><p className="text-xs font-semibold text-muted">适用条件</p>{readableConditions.length?<div className="mt-2 space-y-2">{readableConditions.map((condition,index)=><div className="rounded-lg bg-surface-2 px-3 py-2 text-sm" key={`${condition.expression}-${index}`}>{condition.message||'必须满足'} <span className="formula-code text-muted">（{condition.expression}）</span></div>)}</div>:<p className="mt-2 text-sm text-muted">未填写额外限制。</p>}</div><div className="rounded-xl bg-surface-2 p-4 text-sm"><p className="text-xs font-semibold text-muted">验算样例</p><p className="mt-2"><span className="text-muted">输入：</span>{Object.entries(readableExample).map(([key,value])=><span className="mr-3" key={key}><b>{key}</b> = {String(value)}</span>)}</p><p className="mt-2"><span className="text-muted">预期结果：</span><b>{draft.expected||'—'}</b><span className="ml-4 text-muted">允许误差：</span><b>{draft.tolerance||'—'}</b></p></div></div><details className="mt-6 rounded-xl border border-border"><summary className="cursor-pointer px-4 py-3 text-sm font-semibold">高级设置（实现细节，可选）</summary><div className="grid gap-4 border-t border-border p-4 lg:grid-cols-2"><Field label="受限计算表达式"><Input value={draft.expression} onChange={e=>change('expression',e.target.value)} placeholder="只允许数学表达式和白名单函数"/></Field><Field label="结果参数名"><Input value={draft.result_key} onChange={e=>change('result_key',e.target.value)} placeholder="例如 N 或 C"/></Field><Field label="参数 JSON"><textarea className="mt-1 min-h-40 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.variables} onChange={e=>change('variables',e.target.value)}/></Field><Field label="依赖公式编号（逗号分隔）"><Input value={draft.dependencies} onChange={e=>change('dependencies',e.target.value)} placeholder="例如 10.2.1-1, 10.2.1-2"/></Field><Field label="适用条件 JSON"><textarea className="mt-1 min-h-32 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.conditions} onChange={e=>change('conditions',e.target.value)} placeholder={'[{"expression":"x > 0","message":"原文限制"}]'}/></Field><Field label="查表 / 插值 JSON（留空则代数式）"><textarea className="mt-1 min-h-32 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.table} onChange={e=>change('table',e.target.value)} placeholder={'{"input":"x","output":"y","rows":[{"x":1,"y":2}]}'}/></Field><Field label="验算输入 JSON"><textarea className="mt-1 min-h-24 w-full rounded-xl border border-border bg-surface p-3 font-mono text-xs" value={draft.example_inputs} onChange={e=>change('example_inputs',e.target.value)}/></Field><div className="grid grid-cols-2 gap-3"><Field label="预期结果"><Input value={draft.expected} onChange={e=>change('expected',e.target.value)}/></Field><Field label="容差"><Input value={draft.tolerance} onChange={e=>change('tolerance',e.target.value)}/></Field></div></div></details>{tablePreview?.rows&&<div className="mt-4 overflow-auto rounded-xl border border-border"><table><thead><tr>{Object.keys(tablePreview.rows[0]||{}).map(key=><th key={key}>{key}</th>)}</tr></thead><tbody>{tablePreview.rows.map((row,index)=><tr key={index}>{Object.values(row).map((value,column)=><td key={column}>{value}</td>)}</tr>)}</tbody></table></div>}{related.length>0&&<div className="mt-4 rounded-xl bg-surface-2 p-4"><b>与当前公式有关的已编号公式</b><div className="mt-2 flex flex-wrap gap-2">{related.map(item=><span key={`${item.code}-${item.direction}`} className="rounded-lg bg-surface px-3 py-2 text-sm"><b className="formula-code">{item.code}</b> · {item.name} <small className="text-muted">{item.direction==='selected'?'当前':item.direction==='dependency'?'引用':'被引用'} · {item.status}</small></span>)}</div></div>}<Button className="mt-5" onClick={()=>void save()}>保存草稿版本</Button>{notice&&<p className="mt-3 text-sm text-muted">{notice}</p>}{validation&&<p className="mt-2 text-sm font-medium text-brand">{validation}</p>}</Card></div></div></div>}
function CalculationChainManager({token}:{token:string}){
  const [formulas,setFormulas]=useState<Formula[]>([]);
  const [targetId,setTargetId]=useState<number|null>(null);
  const [chain,setChain]=useState<string[]>([]);
  const [notice,setNotice]=useState('');
  const load=()=>void request<{items:Formula[]}>('/api/admin/catalog',token).then(data=>{setFormulas(data.items);setTargetId(current=>data.items.some(item=>item.id===current)?current:data.items[0]?.id||null)});
  useEffect(load,[token]);
  const target=formulas.find(item=>item.id===targetId);
  useEffect(()=>setChain(target?.rule.calculation_chain||[]),[targetId,formulas]);
  const move=(code:string,offset:number)=>setChain(current=>{const index=current.indexOf(code);const next=index+offset;if(index<0||next<0||next>=current.length)return current;const copy=[...current];[copy[index],copy[next]]=[copy[next],copy[index]];return copy});
  const save=async()=>{if(!target)return;try{const response=await request<{version_id:number}>('/api/admin/formulas/'+target.id+'/calculation-chain',token,'POST',{predecessor_codes:chain});setNotice(`已创建草稿版本 v${target.version+1}（#${response.version_id}）。请在上方公式审核区提交审核、验算并确认发布。`);load()}catch(error){setNotice((error as Error).message)}};
  return <Card className="p-6"><Badge tone="warn">计算链审核配置</Badge><h2 className="mt-3 font-bold">选择目标公式与前置公式</h2><p className="mt-1 text-sm leading-6 text-muted">编号顺序不等于数学依赖。这里定义用户端的计算包顺序；受限表达式中的“依赖公式编号”仍用于校验和自动回带。</p><Field label="目标公式（通常是本条的 -1 公式）"><select className="mt-1 h-10 w-full rounded-xl border border-border bg-surface px-3 text-sm" value={targetId||''} onChange={event=>setTargetId(Number(event.target.value))}>{formulas.map(item=><option key={item.id} value={item.id}>{item.code} · {item.name} · v{item.version} {item.status}</option>)}</select></Field><div className="mt-5 grid gap-5 lg:grid-cols-2"><div><b className="text-sm">可选前置公式</b><div className="mt-2 max-h-64 space-y-2 overflow-auto rounded-xl bg-surface-2 p-3">{formulas.filter(item=>item.id!==targetId).map(item=>{const checked=chain.includes(item.code);return <label className="flex cursor-pointer items-start gap-3 rounded-lg bg-surface p-3 text-sm" key={item.id}><input className="mt-1 accent-brand" type="checkbox" checked={checked} onChange={()=>setChain(current=>checked?current.filter(code=>code!==item.code):[...current,item.code])}/><span><b className="formula-code">{item.code}</b><span> · {item.name}</span><small className="mt-1 block text-xs text-muted">v{item.version} · {item.status}</small></span></label>})}</div></div><div><b className="text-sm">计算顺序（前置 → 目标）</b><div className="mt-2 min-h-32 space-y-2 rounded-xl bg-surface-2 p-3">{chain.length===0?<p className="text-sm text-muted">未选择前置公式；用户端仅计算目标公式及其数学依赖。</p>:chain.map((code,index)=>{const item=formulas.find(formula=>formula.code===code);return <div className="flex items-center justify-between gap-2 rounded-lg bg-surface p-3 text-sm" key={code}><span><b className="mr-2 text-brand">{index+1}</b><b className="formula-code">{code}</b> · {item?.name||'公式'}</span><span className="flex gap-1"><Button type="button" size="sm" variant="outline" disabled={index===0} onClick={()=>move(code,-1)}>↑</Button><Button type="button" size="sm" variant="outline" disabled={index===chain.length-1} onClick={()=>move(code,1)}>↓</Button></span></div>})}<div className="rounded-lg border border-dashed border-brand/30 bg-brand/5 p-3 text-sm font-semibold text-brand">目标：{target?`${target.code} · ${target.name}`:'—'}</div></div></div></div><Button className="mt-5" type="button" onClick={()=>void save()} disabled={!target}>保存为待审核计算链</Button>{notice&&<p className="mt-3 text-sm leading-6 text-muted">{notice}</p>}</Card>
}

function AdminReviewWithChains({token}:{token:string}){return <div className="review-workbench-shell space-y-5"><AdminReview token={token}/><CalculationChainManager token={token}/></div>}

function AdminDialog({close,signIn}:{close:()=>void;signIn:(username:string,password:string)=>Promise<void>}){const [error,setError]=useState('');const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await signIn(String(form.get('username')),String(form.get('password')));close()}catch(x){setError((x as Error).message)}};return <div className="fixed inset-0 z-50 grid place-items-center bg-fg/20 p-4"><Card className="w-full max-w-sm p-6"><div className="flex items-start justify-between gap-4"><div><Badge tone="warn">后端调试入口</Badge><h2 className="mt-3 text-xl font-bold">管理员登录</h2><p className="mt-1 text-sm text-muted">仅管理员可进入审核、发布与 OCR 资料库。</p></div><button className="text-muted" onClick={close}>×</button></div><form className="mt-5 grid gap-4" onSubmit={submit}><Field label="管理员账号"><Input name="username" defaultValue="admin" required/></Field><Field label="密码"><Input name="password" type="password" defaultValue="admin123" required/></Field><Button>进入管理员模式</Button></form>{error&&<p className="mt-3 rounded-lg bg-danger/10 p-3 text-sm text-danger">{error}</p>}</Card></div>}
function App(){
  const [token,setToken]=useState<string|null>(null);const [user,setUser]=useState<User|null>(null);const [adminOpen,setAdminOpen]=useState(false);
  const signIn=async(username:string,password:string)=>{const login=await request<{token:string}>('/api/login',null,'POST',{username,password});setToken(login.token);setUser(await request<User>('/api/me',login.token))};
  useEffect(()=>{void signIn('user','user123').catch(()=>undefined)},[]);
  if(!token||!user)return <main className="grid min-h-screen place-items-center text-sm text-muted">正在打开本地计算界面…</main>;
  return <BrowserRouter><Layout user={user} onAdminLogin={()=>setAdminOpen(true)} onReturnUser={()=>void signIn('user','user123')}><Routes>
    <Route path="/" element={user.role==='admin'?<Home token={token}/>:<Navigate to="/calculator" replace/>}/>
    <Route path="/calculator" element={<CalculatorWorkspace token={token} isAdmin={user.role==='admin'}/>}/><Route path="/standards" element={<Standards token={token}/>}/>
    {user.role==='admin'&&<><Route path="/review" element={<AdminReviewWithChains token={token}/>}/><Route path="/ocr" element={<Review token={token} ocr/>}/></>}
    <Route path="*" element={<Navigate to="/" replace/>}/>
  </Routes>{adminOpen&&<AdminDialog close={()=>setAdminOpen(false)} signIn={signIn}/>}</Layout></BrowserRouter>
}
