function MathFormula({K,n,Fx,Fy,alpha,beta,result}:{K:string;n:string;Fx:string;Fy:string;alpha:string;beta:string;result?:{value:number;unit:string}|null}){
  const variables=K==='K';
  const top=(value:string)=>variables?`<mi>${value}</mi>`:`<mn>${value}</mn>`;
  const force=(axis:'x'|'y')=>variables?`<mrow><mo>∑</mo><msub><mi>F</mi><mi>${axis}</mi></msub></mrow>`:`<mn>${axis==='x'?Fx:Fy}</mn>`;
  const angle=(value:string)=>variables?`<mi>${value}</mi>`:`<mrow><mn>${value}</mn><mo>°</mo></mrow>`;
  const denominator=(kind:'sin'|'cos')=>`<mrow><mi mathvariant="normal">${kind}</mi>${angle(alpha)}<mo>×</mo><mi mathvariant="normal">cos</mi>${angle(beta)}</mrow>`;
  const prefix=`<mi>N</mi><mo>=</mo><mfrac>${top(K)}${top(n)}</mfrac><mo>×</mo><mo>[</mo>`;
  const first=`<mfrac>${force('x')}${denominator('sin')}</mfrac>`;
  const second=`<mfrac>${force('y')}${denominator('cos')}</mfrac>`;
  const markup=result
    ?`<span class="formula-calculation"><math display="block"><mrow>${prefix}${first}<mo>+</mo></mrow></math><math display="block"><mrow>${second}<mo>]</mo><mo>=</mo><mstyle class="formula-result" mathvariant="bold"><mrow><mn>${result.value.toFixed(2)}</mn><mtext>&nbsp;${result.unit}</mtext></mrow></mstyle></mrow></math></span>`
    :`<math display="block"><mrow>${prefix}${first}<mo>+</mo>${second}<mo>]</mo></mrow></math>`;
  return <span className="stix-formula" dangerouslySetInnerHTML={{__html:markup}}/>;
}
const normalizeLatex=(latex:string)=>latex.replace(/\\\\(?=(?:frac|sin|cos|left|right|sum|mathrm|text|cdot|sqrt|alpha|beta))/g,'\\');
const withExplicitMultiplication=(latex:string)=>normalizeLatex(latex).replace(/(?<=[0-9}])(?=\\(?:sin|cos|left))/g,'\\times ');
function LatexFormula({latex}:{latex:string}){const normalized=useMemo(()=>normalizeLatex(latex),[latex]);const markup=useMemo(()=>katex.renderToString(normalized,{displayMode:true,output:'mathml',throwOnError:false,strict:'ignore'}),[normalized]);return <span className="stix-formula" dangerouslySetInnerHTML={{__html:markup}}/>}
function FormulaExpression({formula,values,result,referenceKeys=new Set<string>()}:{formula?:Formula;values:Record<string,string>;result:Record<string,ResultValue>|null;referenceKeys?:Set<string>}){
  const final=formula&&result?.[formula.code];
  const number=(value:string)=>Number.isFinite(Number(value))?String(Number(value)):'?';
  if(!formula)return null;
  const standardMooring=formula.code==='10.2.1-1';
  const substitution=formula.rule.substitution_latex;
  const dependencyN=values.N?.trim()||result?.['10.2.1-1']?.value.toFixed(2);
  const reference=(key:string,value:string)=>referenceKeys.has(key)?`\\textcolor{#C55300}{${value}}`:value;
  const displayLatex=Array.from(referenceKeys).reduce((latex,key)=>latex.replace(new RegExp(`\\b${key}\\b`,'g'),reference(key,key)),formula.latex);
  const substitutedLatex=final?`${withExplicitMultiplication((substitution||formula.latex).replace(/\bN\b/g,reference('N',dependencyN||'N')).replace(/Σ?F_x/g,number(values.Fx)).replace(/Σ?F_y/g,number(values.Fy)).replace(/\\alpha|α/g,`${number(values.alpha)}^{\\circ}`).replace(/\\beta|β/g,`${number(values.beta)}^{\\circ}`).replace(/\bK\b/g,number(values.K)).replace(/\bn\b/g,number(values.n)))}=\\underline{\\mathbf{${final.value.toFixed(2)}}}\\,\\mathrm{${final.unit}}`:'';
  return <div className="mt-4 rounded-xl border border-brand/20 bg-brand/5 p-4 text-sm"><p className="text-center font-semibold text-brand">规范计算公式</p><div className="formula-viewport mt-3">{standardMooring?<MathFormula K="K" n="n" Fx="" Fy="" alpha="α" beta="β"/>:<LatexFormula latex={displayLatex}/>}</div>{formula.rule.conditions?.length?<div className="mt-3 rounded-lg bg-surface/70 p-3 text-xs text-muted"><b className="text-fg">适用限制</b>{formula.rule.conditions.map((condition,index)=><p className="mt-1" key={index}>{condition.message||condition.expression}</p>)}</div>:null}{final&&<><p className="mt-4 text-center font-semibold text-brand">本次参数代入</p><div className="formula-viewport mt-3">{standardMooring?<MathFormula K={number(values.K)} n={number(values.n)} Fx={number(values.Fx)} Fy={number(values.Fy)} alpha={number(values.alpha)} beta={number(values.beta)} result={final}/>:<LatexFormula latex={substitutedLatex}/>}</div></>}</div>
}

