        <Card className="pdf-reference-panel p-6"><div className="flex items-start justify-between gap-4"><div><Badge tone="brand">规范原文 PDF</Badge><h2 className="mt-3 font-bold">{focus?`${focus.code} · ${focus.name}`:'选择公式查看出处'}</h2></div><a className="text-sm font-semibold text-brand" href={source} target="_blank" rel="noreferrer">跳转到原文页 ↗<small className="mt-1 block text-right text-xs font-normal text-muted">PDF 第 {page} 页</small></a></div><StandardPdfPreview page={page}/></Card>
